<?php require_once __DIR__.'/config.php'; csrf_check(); if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??''; $id=(int)($_POST['product_id']??0); if($action==='add' && $id>0){$s=db()->prepare('SELECT id,price,stock,active FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch();if($p && $p['active'] && $p['price']!==null && (float)$p['price']>0 && $p['stock']>0){$qty=max(1,(int)($_POST['quantity']??1));$_SESSION['cart'][$id]=min((int)$p['stock'],(int)($_SESSION['cart'][$id]??0)+$qty);flash('Product added to your cart.');}else flash('This product is not available for purchase yet.','error');} elseif($action==='update'){foreach(($_POST['qty']??[]) as $pid=>$qty){$pid=(int)$pid;$qty=(int)$qty;if($qty<1)unset($_SESSION['cart'][$pid]);else{$_SESSION['cart'][$pid]=min(99,$qty);}}flash('Cart updated.');} elseif($action==='remove'){unset($_SESSION['cart'][$id]);flash('Item removed from cart.');} header('Location: /powervault/cart.php');exit; }
$pageTitle='Your Cart';$cart=$_SESSION['cart']??[];$items=[];$subtotal=0;if($cart){$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT * FROM products WHERE id IN ($in) AND active=1");$s->execute($ids);foreach($s->fetchAll() as $p){if($p['price']!==null){$qty=min((int)$cart[$p['id']],max(0,(int)$p['stock']));if($qty>0){$p['qty']=$qty;$p['line']=(float)$p['price']*$qty;$subtotal+=$p['line'];$items[]=$p;}}}}require __DIR__.'/includes/header.php'; ?>
<section class="page-hero compact"><div class="container"><div class="eyebrow">YOUR SELECTION</div><h1>Shopping <span class="gradient-text">Cart</span></h1></div></section><section class="section-pad"><div class="container"><?=get_flash()?><?php if(!$items): ?><div class="empty-state"><div class="empty-icon">⌑</div><h2>Your cart is waiting.</h2><p>Add a product with a configured price to get started.</p><a class="btn btn-neon" href="/powervault/shop.php">Explore Products</a></div><?php else: ?><div class="row g-4"><div class="col-lg-8"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><?php foreach($items as $it): ?><div class="cart-row"><div class="cart-thumb"><span class="device-bolt">ϟ</span></div><div class="cart-item-copy"><h3><?=e($it['name'])?></h3><p><?=e($it['category']?:'POWERVAULT')?></p><strong><?=money($it['price'])?></strong></div><div class="cart-qty"><label>Qty</label><input type="number" name="qty[<?=$it['id']?>]" min="0" max="<?=max(1,(int)$it['stock'])?>" value="<?=$it['qty']?>" class="form-control"></div><div class="cart-line"><?=money($it['line'])?><form></form><button type="submit" form="remove<?=$it['id']?>" class="remove-link">Remove</button></div></div><?php endforeach; ?><button class="btn btn-outline-glow mt-3">Update Cart</button></form><?php foreach($items as $it): ?><form id="remove<?=$it['id']?>" method="post" class="d-none"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=$it['id']?>"></form><?php endforeach; ?></div><div class="col-lg-4"><div class="summary-card"><h3>Order Summary</h3><div class="summary-line"><span>Subtotal</span><b><?=money($subtotal)?></b></div><div class="summary-line"><span>Shipping</span><b><?=money((float)SHIPPING_CHARGE)?></b></div><div class="summary-line total"><span>Estimated total</span><b><?=money($subtotal+(float)SHIPPING_CHARGE)?></b></div><p class="muted small">A 3% discount applies to eligible Easypaisa and JazzCash orders at checkout.</p><a class="btn btn-neon w-100" href="/powervault/checkout.php">Proceed to Checkout →</a></div></div></div><?php endif; ?></div></section><?php require __DIR__.'/includes/footer.php'; ?>
